import itertools

def srem(x, n):
    """Signed remainder in Python (matches LLVM srem)"""
    if n == 0:
        return None  # UB
    # Python's % gives remainder with sign of divisor
    # LLVM srem gives remainder with sign of dividend
    return x - (int(x / n) * n)

def test_all(bits=4):
    for n in range(1 << bits):
        if n == 0:
            continue
        # Check if n is power of two
        if n & (n - 1) != 0:
            continue

        for x in range(-(1 << (bits-1)), 1 << (bits-1)):
            rem = srem(x, n)
            if rem is None:
                continue
            cmp = rem < 0
            add = rem + n
            sel = add if cmp else rem

            # x & (n - 1)
            and_val = x & (n - 1)

            if sel != and_val:
                print(f"ERROR: x={x}, n={n}, rem={rem}, cmp={cmp}, add={add}, sel={sel}, and={and_val}")
                return False
    print(f"All tests passed for {bits}-bit integers")
    return True

if __name__ == "__main__":
    for bits in [4, 5, 6]:
        test_all(bits)
